#include <iostream>
#include <vector>
#include <string>
#include <unordered_map>
#include <sstream>
#include <algorithm>
using namespace std;

vector<int> findSubstring(string s, vector<string>& words) {
    vector<int> res;
    if (s.empty() || words.empty()) return res;
    int n = s.length(), m = words.size(), l = words[0].length();
    unordered_map<string, int> counts;
    for (string w : words) counts[w]++;
    for (int i = 0; i < l; i++) {
        int left = i, count = 0;
        unordered_map<string, int> curr;
        for (int j = i; j <= n - l; j += l) {
            string w = s.substr(j, l);
            if (counts.count(w)) {
                curr[w]++;
                count++;
                while (curr[w] > counts[w]) {
                    curr[s.substr(left, l)]--;
                    count--;
                    left += l;
                }
                if (count == m) res.push_back(left);
            } else {
                curr.clear();
                count = 0;
                left = j + l;
            }
        }
    }
    return res;
}

int main() {
    string s, line;
    if (getline(cin, s)) {
        if (getline(cin, line)) {
            if (s.front() == '"') s = s.substr(1, s.size() - 2);
            if (line.front() == '[') line = line.substr(1, line.size() - 2);
            stringstream ss(line);
            vector<string> words;
            string w;
            while (getline(ss, w, ',')) {
                while (!w.empty() && (w.front() == ' ' || w.front() == '"')) w.erase(0, 1);
                while (!w.empty() && (w.back() == ' ' || w.back() == '"')) w.pop_back();
                if (!w.empty()) words.push_back(w);
            }
            vector<int> res = findSubstring(s, words);
            cout << "[";
            for (int i = 0; i < res.size(); i++) cout << (i == 0 ? "" : ",") << res[i];
            cout << "]" << endl;
        }
    }
    return 0;
}

