import java.util.*;
import java.io.*;

public class Main {
    public static List<Integer> findSubstring(String s, String[] words) {
        List<Integer> res = new ArrayList<>();
        if (s == null || words == null || words.length == 0) return res;
        int n = s.length(), m = words.length, l = words[0].length();
        Map<String, Integer> counts = new HashMap<>();
        for (String w : words) counts.put(w, counts.getOrDefault(w, 0) + 1);
        for (int i = 0; i < l; i++) {
            int left = i, count = 0;
            Map<String, Integer> curr = new HashMap<>();
            for (int j = i; j <= n - l; j += l) {
                String w = s.substring(j, j + l);
                if (counts.containsKey(w)) {
                    curr.put(w, curr.getOrDefault(w, 0) + 1);
                    count++;
                    while (curr.get(w) > counts.get(w)) {
                        String first = s.substring(left, left + l);
                        curr.put(first, curr.get(first) - 1);
                        count--;
                        left += l;
                    }
                    if (count == m) res.add(left);
                } else {
                    curr.clear();
                    count = 0;
                    left = j + l;
                }
            }
        }
        return res;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine();
        String line = br.readLine();
        if (s != null && line != null) {
            s = s.replaceAll("^\"", "").replaceAll("\"$", "");
            line = line.replace("[", "").replace("]", "").trim();
            String[] parts = line.split(",");
            String[] words = new String[parts.length];
            for (int i = 0; i < parts.length; i++) words[i] = parts[i].trim().replace("\"", "");
            List<Integer> res = findSubstring(s, words);
            System.out.println(res.toString().replace(" ", ""));
        }
    }
}

