const fs = require('fs');

function findSubstring(s, words) {
    if (!s || !words.length) return [];
    const L = words[0].length, m = words.length, n = s.length;
    const counts = {};
    for (const w of words) counts[w] = (counts[w] || 0) + 1;
    const res = [];
    for (let i = 0; i < L; i++) {
        let left = i, count = 0;
        const curr = {};
        for (let j = i; j <= n - L; j += L) {
            const w = s.substring(j, j + L);
            if (counts[w]) {
                curr[w] = (curr[w] || 0) + 1;
                count++;
                while (curr[w] > counts[w]) {
                    const first = s.substring(left, left + L);
                    curr[first]--;
                    count--;
                    left += L;
                }
                if (count === m) res.push(left);
            } else {
                for (let k in curr) delete curr[k];
                count = 0;
                left = j + L;
            }
        }
    }
    return res;
}

